package com.sergio.financial.goal;
import jakarta.validation.Valid; import java.time.YearMonth; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/savings-goals") public class SavingsGoalController {private final SavingsGoalService s; public SavingsGoalController(SavingsGoalService s){this.s=s;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public SavingsGoalResponse create(@Valid @RequestBody SavingsGoalRequest r,Authentication a){return s.create(id(a),r);}@GetMapping public List<SavingsGoalResponse> list(@RequestParam YearMonth month,Authentication a){return s.list(id(a),month);}@PutMapping("/{goalId}/months/{month}") public SavingsGoalResponse update(@PathVariable Long goalId,@PathVariable YearMonth month,@Valid @RequestBody SavingsGoalMonthRequest r,Authentication a){return s.update(id(a),goalId,month,r);}@DeleteMapping("/{goalId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long goalId,Authentication a){s.delete(id(a),goalId);}private Long id(Authentication a){return Long.valueOf(a.getName());}}
